import csv
from collections import defaultdict

values = defaultdict(list)
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        values[r['timeseries_id']].append((r['timestamp'], float(r['value'])))
for k in values:
    values[k].sort()

core = {
    'F2_Z01 coolSP': '1213f3a8-c23d-55b5-8187-4712d49a82ae',
    'F2_Z01 T': 'baef86cb-2941-5d61-87b0-ffa91d79f23a',
    'F2_Z01 OCCcoolSP': 'c5120bcb-e5c2-5714-a171-cbdb1f8ef5ab',
    'F3_Z01 T': 'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
    'F4_Z01 T': '14a08406-79a0-52ca-b8a1-8563259dc820',
}

def mean(vals):
    return sum(v[1] for v in vals)/len(vals)

# Before period: 1 Jan to 14 June 2018 (occupied hours 7-18); after: 16 Jun to 31 Dec
def filter_range(tsid):
    res=[]
    for ts,v in values[tsid]:
        d = ts[:10]
        if '2018-01-01' <= d <= '2018-14-06':
            h=int(ts[11:13])
            if 7<=h<=18:
                res.append((ts,v))
    return res

def filter_after(tsid):
    res=[]
    for ts,v in values[tsid]:
        d = ts[:10]
        if '2018-16-06' <= d <= '2018-12-31':
            h=int(ts[11:13])
            if 7<=h<=18:
                res.append((ts,v))
    return res

for name,tsid in core.items():
    b=filter_range(tsid); a=filter_after(tsid)
    print(name, "before mean=", round(mean(b),3), "after mean=", round(mean(a),3), "delta=", round(mean(a)-mean(b),3))
